const { eventTypeId, start, attendeeName, attendeeEmail, attendeeTimeZone, notes, metadata } = $.input;
if (!eventTypeId || !start || !attendeeName || !attendeeEmail) throw new Error('eventTypeId, start, attendeeName, and attendeeEmail are required');
const body = {
  eventTypeId,
  start,
  attendee: {
    name: attendeeName,
    email: attendeeEmail,
    timeZone: attendeeTimeZone || 'America/New_York'
  }
};
if (notes) body.notes = notes;
if (metadata) body.metadata = metadata;
return body;

const resp = $.steps.createBooking.response || {};
const booking = resp.data || resp;
return {
  bookingId: booking.id || booking.uid || '',
  uid: booking.uid || '',
  title: booking.title || '',
  startTime: booking.startTime || $.input.start,
  endTime: booking.endTime || '',
  status: booking.status || '',
  created: !!(booking.id || booking.uid),
  summary: (booking.id || booking.uid)
    ? `Booked "${booking.title || 'event'}" for ${$.input.attendeeName}`
    : 'Failed to create booking'
};
